def rewrite_sentence(sentence):
    # Define the span types and their corresponding tags
    span_types = {
        'claim': '<claim>',
        'premise': '<premise>'
    }

    # Split the sentence into words
    words = sentence.split()

    # Initialize variables to store the current span type and its content
    current_span_type = None
    current_span_content = ''

    # Iterate over each word in the sentence
    for i, word in enumerate(words):
        # Check if the word is a claim or premise indicator
        if word.lower() == 'who' or word.lower() == 'why':
            # If it's an indicator, check if we're currently inside a span
            if current_span_type is not None:
                # If we are, append the word to the current span's content
                current_span_content +='' + word
            else:
                # If we're not, start a new span with the indicator as its content
                current_span_type = 'claim'
                current_span_content = word
        elif word.lower() == 'for' or word.lower() == 'because':
            # If it's a conjunction, check if we're currently inside a span
            if current_span_type is not None:
                # If we are, append the word to the current span's content
                current_span_content +='' + word
            else:
                # If we're not, start a new span with the conjunction as its content
                current_span_type = 'premise'
                current_span_content = word
        else:
            # If it's not an indicator or conjunction, check if we're currently inside a span
            if current_span_type is not None:
                # If we are, append the word to the current span's content
                current_span_content +='' + word
            else:
                # If we're not, just append the word to the output
                pass

        # If we've reached the end of the sentence, close the current span (if any)
        if i == len(words) - 1:
            if current_span_type is not None:
                # Close the current span with its tag
                print(span_types[current_span_type] + current_span_content + span_types[current_span_type], end=' ')

    return ''

