import re

def tag_sentence(sentence):
    # Define regular expressions to match claims and premises
    claim_pattern = r"\b(apparent|very)\s+(humanitarian|specific)\b"
    premise_pattern = r"\b(within|of)\s+\d+"

    # Find all matches for claims and premises
    claims = re.findall(claim_pattern, sentence)
    premises = re.findall(premise_pattern, sentence)

    # Tag the matched spans
    for i, claim in enumerate(claims):
        start = sentence.find(claim) + len(claim)
        end = sentence.find(',', start)
        if end == -1:
            end = len(sentence)
        sentence = sentence[:start] + "<claim>" + sentence[start:end] + "</claim>" + sentence[end:]

    for i, premise in enumerate(premises):
        start = sentence.find(premise) + len(premise)
        end = sentence.find(' ', start)
        if end == -1:
            end = len(sentence)
        sentence = sentence[:start] + "<premise>" + sentence[start:end] + "</premise>" + sentence[end:]

    return sentence

