import nltk
from nltk import word_tokenize

def annotate_sentence(sentence):
    tokens = word_tokenize(sentence)
    annotated_tokens = []

    for i, token in enumerate(tokens):
        if token.lower() == 'because':
            annotated_tokens.append('<claim>' + token + '</claim>')
        elif token.lower() in ['here', 'elsewhere'] and i > 0 and tokens[i-1].lower()!= 'de' and tokens[i-1].lower()!= 'escalate':
            annotated_tokens.append('<premise>' + token + '</premise>')
        else:
            annotated_tokens.append(token)

    return''.join(annotated_tokens)

